.circular-container { padding: 24px; background: linear-gradient(180deg, #d8f3dc 0%, #b7e4c7 100%); min-height: 100vh; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1b4332; } .circular-header { background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 100%); color: #d8f3dc; padding: 32px; border-radius: 24px; margin-bottom: 28px; text-align: center; box-shadow: 0 12px 32px rgba(27,67,50,0.25); } .circular-header h1 { font-size: 1.9rem; font-weight: 700; margin: 0 0 8px 0; letter-spacing: -0.02em; } .circular-header p { font-size: 1.1rem; margin: 0; color: #95d5b2; } .circular-period-bar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 24px; padding: 16px 24px; background: #ffffff; border-radius: 16px; box-shadow: 0 6px 20px rgba(0,0,0,0.08); } .circular-period-info { display: flex; align-items: center; gap: 8px; font-size: 0.95rem; color: #2d6a4f; font-weight: 600; } .circular-period-info span:nth-child(2), .circular-period-info span:nth-child(4) { color: #1b4332; font-weight: 700; font-size: 1.2rem; } .circular-phase-badge { background: #d8f3dc; color: #1b4332; padding: 8px 20px; border-radius: 20px; font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; border: 2px solid #52b788; } .circular-kpi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-bottom: 28px; } @media (max-width: 768px) { .circular-kpi-grid { grid-template-columns: 1fr; } } .circular-kpi-card { background: #ffffff; border-radius: 20px; padding: 24px; border-top: 5px solid #52b788; box-shadow: 0 6px 20px rgba(0,0,0,0.08); transition: transform 0.2s ease; } .circular-kpi-card:hover { transform: translateY(-4px); } .circular-kpi-card:nth-child(2) { border-top-color: #40916c; } .circular-kpi-card:nth-child(3) { border-top-color: #2d6a4f; } .circular-kpi-card:nth-child(4) { border-top-color: #1b4332; } .circular-kpi-card:nth-child(5) { border-top-color: #74c69d; } .circular-kpi-card:nth-child(6) { border-top-color: #95d5b2; } .circular-kpi-label { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.08em; color: #52796f; margin-bottom: 10px; font-weight: 700; } .circular-kpi-value { font-size: 1.8rem; font-weight: 700; color: #1b4332; font-family: 'SF Mono', Monaco, monospace; } .circular-main-grid { display: grid; grid-template-columns: 400px 1fr; gap: 28px; margin-bottom: 28px; } @media (max-width: 768px) { .circular-main-grid { grid-template-columns: 1fr; } } .circular-decisions-panel { background: #ffffff; border-radius: 20px; padding: 28px; box-shadow: 0 6px 20px rgba(0,0,0,0.08); } .circular-decisions-panel h3 { color: #2d6a4f; font-size: 1.1rem; text-transform: uppercase; letter-spacing: 0.06em; margin: 0 0 24px 0; padding-bottom: 12px; border-bottom: 2px solid #b7e4c7; } .circular-decision-group { margin-bottom: 20px; } .circular-decision-group label { display: block; font-size: 0.85rem; font-weight: 700; color: #2d6a4f; margin-bottom: 8px; text-transform: uppercase; letter-spacing: 0.04em; } .circular-decision-group select { width: 100%; padding: 12px 16px; background: #ffffff; border: 1px solid #74c69d; border-radius: 12px; font-size: 0.95rem; color: #1b4332; cursor: pointer; transition: all 0.2s ease; } .circular-decision-group select:focus { outline: none; border-color: #2d6a4f; box-shadow: 0 0 0 3px rgba(45,106,79,0.1); } .circular-decision-group select option { background: #ffffff; color: #1b4332; padding: 8px; } .circular-decision-group input[type="range"] { width: 100%; height: 10px; background: #b7e4c7; border-radius: 5px; outline: none; -webkit-appearance: none; margin: 12px 0; } .circular-decision-group input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 22px; height: 22px; background: #2d6a4f; border-radius: 50%; cursor: pointer; box-shadow: 0 2px 8px rgba(27,67,50,0.3); } .circular-decision-group input[type="range"]::-moz-range-thumb { width: 22px; height: 22px; background: #2d6a4f; border-radius: 50%; cursor: pointer; border: none; } .circular-range-labels { display: flex; justify-content: space-between; font-size: 0.8rem; color: #52796f; font-weight: 600; } .circular-range-labels span:nth-child(2) { color: #2d6a4f; font-size: 1rem; } .circular-submit-btn { width: 100%; padding: 16px 24px; margin-top: 12px; background: linear-gradient(135deg, #2d6a4f 0%, #40916c 100%); color: #ffffff; border: none; border-radius: 12px; font-size: 1rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; cursor: pointer; transition: all 0.2s ease; box-shadow: 0 4px 16px rgba(45,106,79,0.3); } .circular-submit-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 24px rgba(45,106,79,0.4); } .circular-visualization-panel { background: #ffffff; border-radius: 20px; padding: 28px; box-shadow: 0 6px 20px rgba(0,0,0,0.08); } .circular-chart-container { height: 260px; margin-bottom: 24px; } .circular-lca-panel { background: #f8f9fa; border-radius: 16px; padding: 20px; margin-bottom: 20px; border: 1px solid #b7e4c7; } .circular-lca-panel h4 { color: #2d6a4f; font-size: 0.9rem; margin: 0 0 16px 0; text-transform: uppercase; letter-spacing: 0.05em; } .circular-lca-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; } .circular-lca-item { display: flex; justify-content: space-between; padding: 10px 14px; background: #ffffff; border-radius: 8px; font-size: 0.85rem; border-left: 3px solid #52b788; } .circular-lca-item span:first-child { color: #52796f; font-weight: 600; } .circular-lca-item span:last-child { color: #1b4332; font-weight: 700; font-family: 'SF Mono', Monaco, monospace; } .circular-event-panel { background: #fef9e7; border: 2px solid #f4d03f; border-radius: 16px; padding: 24px; margin-top: 20px; } .circular-event-title { font-size: 1.1rem; font-weight: 700; color: #7d6608; margin-bottom: 12px; } .circular-event-desc { font-size: 0.95rem; color: #7d6608; line-height: 1.5; margin-bottom: 16px; } .circular-event-choices { display: flex; gap: 12px; flex-wrap: wrap; } .circular-event-btn { padding: 10px 20px; background: #ffffff; border: 2px solid #f4d03f; color: #7d6608; border-radius: 8px; font-weight: 600; cursor: pointer; transition: all 0.15s ease; } .circular-event-btn:hover { background: #f4d03f; color: #7d6608; } .circular-results-panel { background: #ffffff; border: 2px solid #52b788; border-radius: 20px; padding: 28px; margin-bottom: 24px; box-shadow: 0 6px 20px rgba(0,0,0,0.08); } .circular-results-panel h3 { color: #2d6a4f; font-size: 1.2rem; margin: 0 0 20px 0; text-transform: uppercase; letter-spacing: 0.05em; } .circular-results-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; } @media (max-width: 768px) { .circular-results-grid { grid-template-columns: 1fr; } } .circular-result-item { display: flex; justify-content: space-between; padding: 14px 18px; background: #f8f9fa; border-radius: 12px; font-size: 0.9rem; } .circular-result-item span:first-child { color: #52796f; font-weight: 600; } .circular-result-item span:last-child { color: #1b4332; font-weight: 700; font-family: 'SF Mono', Monaco, monospace; } .circular-result-highlight { background: #d8f3dc; border: 1px solid #52b788; } .circular-result-highlight span:last-child { color: #2d6a4f; font-size: 1.1rem; } .circular-result-cost { background: #e8f6f3; border: 1px solid #40916c; } .circular-result-cost span:last-child { color: #1b4332; } .circular-history { margin-bottom: 24px; } .circular-performance-chart { background: #ffffff; border-radius: 20px; padding: 24px; height: 300px; box-shadow: 0 6px 20px rgba(0,0,0,0.08); } .circular-container .table { color: #1b4332; background: #ffffff; } .circular-container .table th { background: #d8f3dc; color: #1b4332; border-color: #b7e4c7; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.05em; font-weight: 700; } .circular-container .table td { border-color: #b7e4c7; color: #2d6a4f; } .circular-container .table-striped tbody tr:nth-of-type(odd) { background: #f8f9fa; }

/* FIX(demo 2026-10-22): the platform stylesheet sets p { text-align: start }, which left the subtitle at the left under the centred title; the header's own alignment applies again */
.circular-header p { text-align: inherit; }

/* ===== Del Residuo al Valor 2.0 design layer (EQIL 2026-10-22). Appended; everything below is scoped to .circular-container.cx ===== */
.circular-container.cx {
    --cx-bg: #f6f2ea; --cx-card: #ffffff; --cx-ink: #2b2418; --cx-ink-2: #463d2e; --cx-ink-3: #5e5444;
    --cx-line: #e3dbcc; --cx-line-2: #cfc3ad; --cx-accent: #1f6f4a; --cx-accent-ink: #185a3c; --cx-accent-soft: #e3f1e8;
    --cx-navy: #3b2a17; --cx-amber: #9a5b1c; --cx-amber-soft: #f8ecdc; --cx-indigo: #8a5a2b; --cx-indigo-soft: #f3eadd;
    --cx-bad: #b42318; --cx-bad-soft: #fdecea; --cx-ok: #166534; --cx-ok-soft: #e7f5ec; --cx-warn-soft: #fff4dc; --cx-focus: #0f4c33;
    --cx-r: 12px; --cx-r-sm: 8px; --cx-s1: 4px; --cx-s2: 8px; --cx-s3: 12px; --cx-s4: 16px; --cx-s5: 24px; --cx-s6: 32px;
    background: var(--cx-bg); color: var(--cx-ink); padding: var(--cx-s4) var(--cx-s5) var(--cx-s6); min-height: auto;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 15px; line-height: 1.45;
    box-sizing: border-box; text-align: left; color-scheme: light;
}
.circular-container.cx *, .circular-container.cx *::before, .circular-container.cx *::after { box-sizing: border-box; }
.circular-container.cx [hidden] { display: none !important; }
.circular-container.cx h1, .circular-container.cx h2, .circular-container.cx h3, .circular-container.cx p,
.circular-container.cx figure, .circular-container.cx dl, .circular-container.cx dd, .circular-container.cx blockquote { margin: 0; }

/* header */
.circular-container.cx .cx-top { display: flex; justify-content: space-between; align-items: flex-end; gap: var(--cx-s4); margin-bottom: var(--cx-s3); flex-wrap: wrap; }
.circular-container.cx .cx-kicker { font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--cx-accent-ink); margin-bottom: 2px; }
.circular-container.cx h1 { font-size: 26px; line-height: 1.15; font-weight: 750; color: var(--cx-ink); letter-spacing: -.01em; text-transform: none; }
.circular-container.cx .cx-progress { display: flex; flex-direction: column; align-items: flex-end; gap: var(--cx-s2); }
.circular-container.cx .cx-counter { font-size: 15px; color: var(--cx-ink-2); display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.circular-container.cx .cx-counter strong { font-size: 22px; color: var(--cx-ink); }
.circular-container.cx .cx-cal { margin-left: var(--cx-s2); background: var(--cx-accent-soft); color: var(--cx-accent-ink); font-weight: 650; font-size: 13px; padding: 2px 10px; border-radius: 999px; }
.circular-container.cx .cx-steps { list-style: none; display: flex; gap: 6px; padding: 0; margin: 0; }
.circular-container.cx .cx-steps li { width: 64px; text-align: center; font-size: 12px; color: var(--cx-ink-3); border-top: 4px solid var(--cx-line-2); padding-top: 3px; border-radius: 2px; }
.circular-container.cx .cx-steps li.is-done { border-top-color: var(--cx-navy); color: var(--cx-ink-2); }
.circular-container.cx .cx-steps li.is-now { border-top-color: var(--cx-accent); color: var(--cx-ink); font-weight: 700; }

/* layout */
.circular-container.cx .cx-grid { display: grid; grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr); gap: var(--cx-s4); align-items: start; }
.circular-container.cx .cx-col { display: flex; flex-direction: column; gap: var(--cx-s3); min-width: 0; }
.circular-container.cx .cx-card { background: var(--cx-card); border: 1px solid var(--cx-line); border-radius: var(--cx-r); padding: var(--cx-s4); box-shadow: 0 1px 2px rgba(59,42,23,.06); }
.circular-container.cx .cx-h2 { font-size: 18px; font-weight: 700; line-height: 1.3; color: var(--cx-ink); }
.circular-container.cx .cx-h3 { font-size: 15px; font-weight: 700; color: var(--cx-ink); margin-bottom: var(--cx-s2); display: block; }
.circular-container.cx .cx-muted { font-size: 13.5px; color: var(--cx-ink-3); }

/* briefing */
.circular-container.cx .cx-brief { border-left: 4px solid var(--cx-accent); }
.circular-container.cx .cx-tag { display: inline-block; font-size: 12px; font-weight: 700; color: var(--cx-accent-ink); background: var(--cx-accent-soft); padding: 2px 10px; border-radius: 999px; margin-bottom: var(--cx-s2); }
.circular-container.cx .cx-brief-text { margin-top: var(--cx-s2); color: var(--cx-ink-2); font-size: 14.5px; }
.circular-container.cx .cx-quote { margin-top: var(--cx-s3); padding: var(--cx-s3) var(--cx-s4); background: var(--cx-navy); color: #fbf6ee; border-radius: var(--cx-r-sm); font-size: 13.5px; line-height: 1.5; }
.circular-container.cx .cx-signal { margin-top: var(--cx-s3); padding: var(--cx-s2) var(--cx-s3); background: var(--cx-amber-soft); border-left: 3px solid var(--cx-amber); border-radius: var(--cx-r-sm); font-size: 13.5px; color: #5c2d05; }

/* KPIs */
.circular-container.cx .cx-kpis { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--cx-s3); }
.circular-container.cx .cx-kpi { background: var(--cx-card); border: 1px solid var(--cx-line); border-radius: var(--cx-r); padding: var(--cx-s3) var(--cx-s4); }
.circular-container.cx .cx-kpi-label { font-size: 13px; font-weight: 600; color: var(--cx-ink-3); }
.circular-container.cx .cx-kpi-value { font-size: 24px; font-weight: 750; color: var(--cx-ink); font-variant-numeric: tabular-nums; margin: 2px 0; }
.circular-container.cx .cx-kpi-value small { font-size: 14px; font-weight: 600; color: var(--cx-ink-3); margin-left: 2px; }
.circular-container.cx .cx-kpi-value.is-neg { color: var(--cx-bad); }
.circular-container.cx .cx-kpi-sub { font-size: 12.5px; color: var(--cx-ink-3); }
.circular-container.cx .cx-up { color: var(--cx-ok); font-weight: 650; }
.circular-container.cx .cx-down { color: var(--cx-bad); font-weight: 650; }
.circular-container.cx .cx-flat { color: var(--cx-ink-3); font-weight: 600; }

/* scorecard */
.circular-container.cx .cx-score-head { display: flex; align-items: center; gap: var(--cx-s3); flex-wrap: wrap; margin-bottom: var(--cx-s2); }
.circular-container.cx .cx-score-head .cx-h3 { margin: 0; flex: 1 1 auto; }
.circular-container.cx .cx-score-n strong { font-size: 24px; font-weight: 750; font-variant-numeric: tabular-nums; }
.circular-container.cx .cx-score-n small { color: var(--cx-ink-3); }
.circular-container.cx .cx-chip { display: inline-block; font-size: 12.5px; font-weight: 700; padding: 3px 10px; border-radius: 999px; border: 1px solid transparent; }
.circular-container.cx .cx-chip-loop { background: var(--cx-ok-soft); color: var(--cx-ok); border-color: #b7e0c4; }
.circular-container.cx .cx-chip-transition { background: var(--cx-accent-soft); color: var(--cx-accent-ink); border-color: #bfdcc9; }
.circular-container.cx .cx-chip-partial { background: var(--cx-warn-soft); color: #7a4a00; border-color: #f2d48f; }
.circular-container.cx .cx-chip-linear { background: var(--cx-amber-soft); color: #8a3c04; border-color: #f4c99a; }
.circular-container.cx .cx-chip-risk { background: var(--cx-bad-soft); color: var(--cx-bad); border-color: #f2b8b2; }
.circular-container.cx .cx-bar { display: grid; grid-template-columns: 11em 1fr 2.5em; gap: var(--cx-s2); align-items: center; font-size: 13.5px; margin: 6px 0; }
.circular-container.cx .cx-bar-l { color: var(--cx-ink-2); }
.circular-container.cx .cx-bar-t { height: 8px; background: #ece4d6; border-radius: 999px; overflow: hidden; }
.circular-container.cx .cx-bar-f { display: block; height: 100%; border-radius: 999px; }
.circular-container.cx .cx-bar-f.f1 { background: var(--cx-accent); }
.circular-container.cx .cx-bar-f.f2 { background: #4f7d2f; }
.circular-container.cx .cx-bar-f.f3 { background: var(--cx-indigo); }
.circular-container.cx .cx-bar-f.f4 { background: var(--cx-navy); }
.circular-container.cx .cx-bar-f.f5 { background: #2f7f8a; }
.circular-container.cx .cx-bar-f.f6 { background: #6b5b45; }
.circular-container.cx .cx-bar-v { text-align: right; font-variant-numeric: tabular-nums; font-weight: 650; color: var(--cx-ink-2); }
.circular-container.cx .cx-gates { display: flex; flex-wrap: wrap; gap: 6px; margin-top: var(--cx-s2); }
.circular-container.cx .cx-gchip { font-size: 12.5px; font-weight: 650; padding: 2px 9px; border-radius: 999px; border: 1px solid; }
.circular-container.cx .cx-gchip.is-ok { color: var(--cx-ok); background: var(--cx-ok-soft); border-color: #b7e0c4; }
.circular-container.cx .cx-gchip.is-no { color: var(--cx-bad); background: var(--cx-bad-soft); border-color: #f2b8b2; }
.circular-container.cx .cx-note { font-size: 12.5px; color: var(--cx-ink-3); margin-top: var(--cx-s2); }

/* result */
.circular-container.cx .cx-res { margin: 0; padding-left: 1.1em; font-size: 14px; color: var(--cx-ink-2); }
.circular-container.cx .cx-res li { margin: 4px 0; }

/* decisions */
.circular-container.cx .cx-dec-head { display: flex; justify-content: space-between; align-items: baseline; gap: var(--cx-s3); flex-wrap: wrap; margin-bottom: var(--cx-s2); }
.circular-container.cx .cx-dec-note { font-size: 13px; color: var(--cx-ink-3); flex: 1 1 14em; text-align: right; }
.circular-container.cx .cx-group { border: 1px solid var(--cx-line); border-radius: var(--cx-r); padding: var(--cx-s1) var(--cx-s4) var(--cx-s2); margin: 0 0 var(--cx-s3); min-width: 0; }
.circular-container.cx .cx-group legend { font-size: 12.5px; font-weight: 750; letter-spacing: .06em; text-transform: uppercase; color: var(--cx-accent-ink); padding: 0 6px; width: auto; float: none; margin: 0; }
.circular-container.cx .cx-field { padding: 6px 0; }
.circular-container.cx .cx-field + .cx-field { border-top: 1px dashed var(--cx-line); }
.circular-container.cx .cx-field-head { display: flex; justify-content: space-between; align-items: center; gap: var(--cx-s2); }
.circular-container.cx .cx-field label { font-size: 14.5px; font-weight: 650; color: var(--cx-ink); margin: 0; }
.circular-container.cx .cx-out { font-variant-numeric: tabular-nums; font-weight: 750; font-size: 14px; color: var(--cx-accent-ink); background: var(--cx-accent-soft); padding: 2px 10px; border-radius: 999px; white-space: nowrap; }
.circular-container.cx input[type="range"] { width: 100%; margin: 4px 0 0; accent-color: var(--cx-accent); height: 24px; background: transparent; cursor: pointer; }
.circular-container.cx .cx-scale { display: flex; justify-content: space-between; font-size: 12.5px; color: var(--cx-ink-3); }
.circular-container.cx .cx-hint { font-size: 13px; color: var(--cx-ink-2); margin-top: 2px; }
.circular-container.cx .cx-preview { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px var(--cx-s2); background: #f8f3ea; border: 1px solid var(--cx-line); border-radius: var(--cx-r); padding: var(--cx-s2) var(--cx-s3); }
.circular-container.cx .cx-pv span { display: block; font-size: 12px; color: var(--cx-ink-3); }
.circular-container.cx .cx-pv strong { font-size: 15px; font-variant-numeric: tabular-nums; color: var(--cx-ink); }
.circular-container.cx .cx-pv.is-neg strong { color: var(--cx-bad); }
.circular-container.cx .cx-preview-note { grid-column: 1 / -1; font-size: 12px; color: var(--cx-ink-3); }
.circular-container.cx .cx-validation { color: var(--cx-bad); font-weight: 600; font-size: 13.5px; margin: 6px 0; }
.circular-container.cx .cx-validation:empty { margin: 4px 0; }
.circular-container.cx .cx-actions { display: flex; gap: var(--cx-s3); flex-wrap: wrap; align-items: center; }
.circular-container.cx .cx-btn { min-height: 44px; padding: 10px 22px; border-radius: 10px; font-weight: 700; font-size: 15px; border: 1px solid transparent; cursor: pointer; font-family: inherit; letter-spacing: 0; text-transform: none; }
.circular-container.cx .cx-btn-primary { background: var(--cx-navy); color: #ffffff; }
.circular-container.cx .cx-btn-primary:hover { background: #24563c; }
.circular-container.cx .cx-btn-primary:disabled { background: #a2967f; cursor: not-allowed; }
.circular-container.cx .cx-btn-ghost { background: transparent; color: var(--cx-ink-2); border-color: var(--cx-line-2); }
.circular-container.cx .cx-btn-ghost:hover { background: #f1ebdf; }
.circular-container.cx :focus-visible { outline: 3px solid var(--cx-focus); outline-offset: 2px; border-radius: 6px; }

/* debrief */
.circular-container.cx .cx-debrief { border-top: 4px solid var(--cx-navy); }
.circular-container.cx .cx-debrief-score { display: flex; align-items: baseline; gap: var(--cx-s2); margin: var(--cx-s2) 0 2px; flex-wrap: wrap; }
.circular-container.cx .cx-debrief-score strong { font-size: 44px; line-height: 1; font-weight: 800; font-variant-numeric: tabular-nums; }
.circular-container.cx .cx-debrief-score small { font-size: 16px; color: var(--cx-ink-3); margin-right: var(--cx-s2); }
