            var title = function (k) { return { display: true, text: self._t(k), color: '#2b2418', font: { size: 13, weight: '600' } }; };
            var leg = { position: 'bottom', labels: { color: ink, boxWidth: 12, usePointStyle: true } };
            return {
                circularityChart: {
                    type: 'line',
                    data: { labels: [], datasets: [
                        { label: self._t('ch_rcy'), data: [], borderColor: '#1f6f4a', backgroundColor: 'rgba(31,111,74,0.10)', borderWidth: 3, fill: false, tension: 0.2, pointRadius: 4 },
                        { label: self._t('ch_rec'), data: [], borderColor: '#9a5b1c', borderWidth: 3, fill: false, tension: 0.2, pointRadius: 4 },
                        { label: self._t('ch_rcy_t'), data: [], borderColor: '#1f6f4a', borderDash: [5, 4], borderWidth: 1.5, fill: false, pointRadius: 0 },
                        { label: self._t('ch_rec_t'), data: [], borderColor: '#9a5b1c', borderDash: [2, 3], borderWidth: 1.5, fill: false, pointRadius: 0 }
                    ] },
                    options: {
                        responsive: true, maintainAspectRatio: false,
                        plugins: { title: title('ch_circ_title'), legend: leg },
                        scales: {
                            y: { beginAtZero: true, min: 0, max: 100, ticks: { color: ink }, grid: { color: grid }, title: { display: true, text: self._t('ch_pct_axis'), color: ink } },
                            x: { ticks: { color: ink }, grid: { color: grid } }
                        }
                    }
                },
                valueChart: {
                    type: 'bar',
                    data: { labels: [], datasets: [
                        { label: self._t('ch_value'), data: [], backgroundColor: [], borderWidth: 0 }
                    ] },
                    options: {
                        responsive: true, maintainAspectRatio: false,
                        plugins: { title: title('ch_value_title'), legend: { display: false } },
                        scales: {
                            y: { beginAtZero: false, ticks: { color: ink }, grid: { color: grid }, title: { display: true, text: self._t('ch_value_axis'), color: ink } },
                            x: { ticks: { color: ink }, grid: { color: grid } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var self = this;
            var ds = (state && state.domainState) || {};
            var h = ds.hist || [];
            var M = CPModel.M;
            var labels = [self._t('cal_start')].concat(h.map(function (r) { return self._t('cal_short_' + r.t); }));
            var rcy = [M.R0], rec = [M.REC0], rt = [M.R_T], ct = [M.REC_T];
            var vlab = h.map(function (r) { return self._t('cal_short_' + r.t); });
            var val = [], col = [];
            for (var i = 0; i < h.length; i++) {
                rcy.push(h[i].R); rec.push(h[i].rec); rt.push(M.R_T); ct.push(M.REC_T);
                var v = (h[i].value || 0) / 1000;
                val.push(Math.round(v * 100) / 100); col.push(v < 0 ? '#b4532a' : '#1f6f4a');
            }
            return {
                circularityChart: { labels: labels, datasets: [{ data: rcy, label: self._t('ch_rcy') }, { data: rec, label: self._t('ch_rec') }, { data: rt, label: self._t('ch_rcy_t') }, { data: ct, label: self._t('ch_rec_t') }] },
                valueChart: { labels: vlab, datasets: [{ data: val, label: self._t('ch_value'), backgroundColor: col }] }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.period', label: 'Semester', i18nKey: 'col_sem', formatter: function (v) { return self._t('cal_short_' + v); } },
                { key: 'results.choiceCode', label: 'Decisions', i18nKey: 'col_dec', formatter: function (v) { return self._choiceText(v); } },
                { key: 'results.recyclable', label: 'Recyclable', i18nKey: 'col_rcy', formatter: function (v) { return self._pct(v); } },
                { key: 'results.recovery', label: 'Recovery', i18nKey: 'col_rec', formatter: function (v) { return self._pct(v); } },
                { key: 'results.ebitdaVsBase', label: 'EBITDA vs plan', i18nKey: 'col_gain', formatter: function (v) { return self._sm(v); } },
                { key: 'results.investment', label: 'Investment', i18nKey: 'col_capex', formatter: function (v) { return self._m(v); } },
                { key: 'results.cashOnHand', label: 'Cash', i18nKey: 'col_cash', formatter: function (v) { return self._m(v); } },
                { key: 'results.overallScore', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        _choiceText(code) {
            if (!code || typeof code !== 'string' || code.indexOf(':') < 0) { return ''; }
            var t = +code.split(':')[0], v = code.split(':')[1].split('|');
            if (t === 1) { return this._t('ch_design_' + v[0]) + ' · ' + this._pct(v[1]) + ' · ' + v[2] + ' g/m²'; }
            if (t === 2) { return this._t('ch_epr_' + v[0]) + ' · ' + this._t('ch_streams', { n: v[1] }); }
            if (t === 3) { return this._t('ch_lca_' + v[0]) + ' · ' + this._pct(v[1]) + ' · +' + this._pct(v[2]); }
            if (t === 4) { return this._t('ch_model_' + v[0]) + ' · ' + this._m(v[1]) + ' · ' + this._t('ch_vc_' + v[2]); }
            return '';
        }

        getHint() { return null; }
        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var last = history[history.length - 1] || {};
            var st = this._state();
            var ds = last.domainState || (st && st.domainState) || {};
            var perf = ds.performance || {};
            var s = typeof perf.overallScore === 'number' ? perf.overallScore : 0;
            var tier = perf.tier || CPModel.tier(s);
            var a = this._analyse(ds);
            var lr = last.results || {};
            return {
                totalPeriods: history.length,
                overallScore: s, composite: s, totalScore: s, score: s,
                outcomeScore: perf.outcome, processScore: perf.process,
                performance: tier, performanceKey: tier, performanceLabel: this._t('perf_' + tier),
                insights: a.insights, turningPoint: a.turning,
                finalRecyclable: lr.recyclable, finalRecovery: lr.recovery, finalCash: lr.cashOnHand, valueFiveYears: perf.value
            };
        }

        formatCompletionMessage(summary) {
            var st = this._state();
            var ds = (st && st.domainState) || {};
            return this._debriefHTML(ds, summary || {});
        }

        /* ---------- reading a run ---------- */
        _flags(ds) {
            var h = ds.hist || [];
            var by = function (t) { for (var i = 0; i < h.length; i++) { if (h[i].t === t) { return h[i]; } } return null; };
            var has = function (r, n) { return !!(r && r.notes.indexOf(n) >= 0); };
            var r1 = by(1), r2 = by(2), r3 = by(3), r4 = by(4);
            return {
                r1: r1, r2: r2, r3: r3, r4: r4,
                keep: ds.design === 'keep', inks: ds.design === 'inks', full: ds.design === 'full', slip: has(r1, 'slip'),
                thin: has(r1, 'thin'), rush: has(r1, 'rush'),
                certs: ds.epr === 'certs', own: ds.epr === 'own', pro: ds.epr === 'pro',
                claim: ds.lca === 'claim', exposed: !!ds.exposed, audit: ds.lca === 'audit', internal: ds.lca === 'internal',
                accept: has(r4, 'accept'), deal: has(r4, 'deal'), walked: !!ds.walked, reject: has(r4, 'reject'),
                nolog: has(r4, 'nologistics'), fined: !!ds.fined, biogasLost: !!ds.symLost, biogasAbsorbed: has(r3, 'biogas_absorbed'),
                kraft: has(r3, 'kraft'), cityGap: has(r4, 'city_gap')
            };
        }

        _analyse(ds) {
            var h = ds.hist || [];
            var ins = [], qs = [];
            if (!h.length) { return { insights: ins, turning: '', questions: qs }; }
            var f = this._flags(ds);
            var last = h[h.length - 1];
            var M = CPModel.M;
            /* the turning point: the first real mistake, named by its cause; otherwise the hardest semester */
            var turning = '';
            if (f.keep) { turning = this._t('tp_keep'); }
            else if (f.certs) { turning = this._t(f.fined ? 'tp_certs' : 'tp_certs_open'); }
            else if (f.claim) { turning = this._t(f.exposed ? 'tp_exposed' : 'tp_claim'); }
            else if (f.thin) { turning = this._t('tp_thin', { g: ds.grammage }); }
            else if (f.accept) { turning = this._t('tp_accept'); }
            else if (f.nolog) { turning = this._t('tp_nolog', { c: this._num(ds.cycles, 1) }); }
            else if (f.walked) { turning = this._t('tp_walked'); }
            else {
                var worst = null;
                for (var i = 1; i < h.length; i++) { var d = h[i].score - h[i - 1].score; if (worst == null || d < worst.d) { worst = { d: d, t: h[i].t }; } }
                turning = (worst && worst.d < 0) ? this._t('tp_none', { m: this._t('cal_' + worst.t), s: last.score }) : this._t('tp_none_up', { s: last.score });
            }
            /* insights built from what this run did */
            if (f.full) { ins.push(this._t('ins_full', { r: this._pct(ds.R), s: f.slip ? this._t('ins_slip') : '' })); }
            else if (f.inks) { ins.push(this._t('ins_inks', { r: this._pct(ds.R) })); }
            else { ins.push(this._t('ins_keep')); }
            if (f.thin) { ins.push(this._t('ins_thin', { g: ds.grammage, d: this._m(ds.damage) })); }
            else { ins.push(this._t('ins_hier', { x: this._pct(ds.rightsize), g: ds.grammage, s: this._m(ds.savings) })); }
            if (f.certs) { ins.push(this._t(f.fined ? 'ins_certs' : 'ins_certs_open', { f: this._m(M.FINE) })); }
            else if (f.own) { ins.push(this._t('ins_own', { r: this._pct(last.rec) })); }
            else if (f.pro) { ins.push(this._t('ins_pro', { f: this._m(CPModel.proFee(ds.R)), r: this._pct(last.rec) })); }
            if (f.exposed) { ins.push(this._t('ins_exposed')); }
            else if (f.claim) { ins.push(this._t('ins_claim')); }
            else if (f.audit && ds.access === 2) { ins.push(this._t('ins_audit', { p: this._pct(ds.premium) })); }
            else if (f.audit) { ins.push(this._t('ins_audit_no')); }
            else if (f.internal) { ins.push(this._t('ins_internal')); }
            if (ds.model === 'paas' || ds.model === 'perf' || ds.model === 'pool') {
                ins.push(this._t(f.deal ? 'ins_plat_deal' : (f.accept ? 'ins_plat_accept' : (f.walked ? 'ins_plat_walked' : 'ins_plat_own')),
                    { c: this._num(ds.cycles, 1), v: this._m(ds.platform), m: this._t('ch_model_' + ds.model) }));
            } else if (ds.model === 'recovery') { ins.push(this._t('ins_plat_recovery')); }
            if (ins.length < 5 && ds.streams > 0) { ins.push(this._t(f.biogasLost ? 'ins_sym_lost' : (f.biogasAbsorbed ? 'ins_sym_absorbed' : 'ins_sym'), { n: ds.streams })); }
            ins = ins.slice(0, 5);
            /* questions for class, from the ORID debrief and the case prompts */
            qs.push(this._t('q_money'));
            qs.push(f.certs || f.keep ? this._t('q_paper') : this._t('q_epr'));
            qs.push(f.accept || f.walked || f.reject ? this._t('q_family_control') : this._t('q_family'));
            return { insights: ins, turning: turning, questions: qs };
        }

        _debriefHTML(ds, summary) {
            var h = ds.hist || [];
            if (!h.length) { return ''; }
            var last = h[h.length - 1], perf = ds.performance || {}, s = perf.overallScore || 0, tier = perf.tier || CPModel.tier(s);
            var a = this._analyse(ds);
            var M = CPModel.M;
            var k = function (label, val) { return '<div class="cx-dkpi"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var rule = function (ok, txt) { return '<li class="' + (ok ? 'is-ok' : 'is-no') + '">' + (ok ? '✓ ' : '✗ ') + txt + '</li>'; };
            var cap = perf.cap ? '<p class="cx-gate">' + this._t('cap_' + perf.cap, { f: this._m(M.FINE) }) + '</p>' : '';
            var ghg = Math.round(ds.ghg + (ds.streams > 0 ? 2 * Math.min(ds.streams, 3) : 0) + (ds.fibre - 68) * 0.4);
            return '<div class="cx-debrief-head">'
                + '<p class="cx-kicker">' + this._t('d_kicker') + '</p>'
                + '<h2 class="cx-h2" id="cxDebriefTitle">' + this._t('d_title') + '</h2>'
                + '<p class="cx-debrief-score"><strong>' + s + '</strong><small>/100</small><span class="cx-chip cx-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + '<p class="cx-debrief-sub">' + this._t('d_sub', { o: perf.outcome, p: perf.process }) + '</p></div>'
                + '<div class="cx-dkpis">'
                + k(this._t('kpi_rcy'), this._pct(ds.R)) + k(this._t('kpi_rec'), this._pct(last.rec)) + k(this._t('d_k_ghg'), '−' + this._pct(ghg))
                + k(this._t('d_k_value'), this._m(perf.value)) + k(this._t('d_k_cycles'), ds.cycles ? this._num(ds.cycles, 1) : '—') + k(this._t('kpi_cash'), this._m(ds.cash)) + '</div>'
                + '<ul class="cx-rules">'
                + rule(last.rec >= M.REC_T && !ds.fined, this._t('d_rule_rec', { v: this._pct(last.rec) }))
                + rule(ds.R >= M.R_T, this._t('d_rule_rcy', { v: this._pct(ds.R) }))
                + rule(ghg >= M.GHG_T, this._t('d_rule_ghg', { v: this._pct(ghg) }))
                + rule(ds.access === 2, this._t('d_rule_panel')) + '</ul>'
                + cap
                + '<h3>' + this._t('d_turning') + '</h3><p class="cx-turning">' + a.turning + '</p>'
                + '<h3>' + this._t('d_insights') + '</h3><ul class="cx-insights">' + a.insights.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>'
                + '<h3>' + this._t('d_questions') + '</h3><ol class="cx-questions">' + a.questions.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ol>';
        }

        /* ---------- painting ---------- */
        _runOver(st) {
            try { if (window.mySimulation && typeof window.mySimulation.isRunComplete === 'function') { return !!window.mySimulation.isRunComplete(); } } catch (e) {}
            var maxP = (st && st.maxPeriods) || CX_R;
            if (st && st.currentPeriod > maxP) { return true; }
            return this._hist(st).length >= maxP;
        }

        _bind() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            var all = [].concat(CX_IDS[1], CX_IDS[2], CX_IDS[3], CX_IDS[4]);
            all.forEach(function (id) {
                var el = document.getElementById(id);
                if (!el) { return; }
                var hnd = function () { try { self._paintOutputs(); self._paintHints(); self._paintPreview(); var v = self._el('cxValidation'); if (v) { v.textContent = ''; } } catch (e) {} };
                el.addEventListener('input', hnd);
                el.addEventListener('change', hnd);
            });
            var relang = function () { try { self._render(); self._relabelCharts(); } catch (e) {} };
            document.addEventListener('express:langchanged', relang);
            var f = window.mySimulation;
            if (f && f.eventBus && typeof f.eventBus.on === 'function') {
                f.eventBus.on('language:changed', relang);
                f.eventBus.on('period:submitted', function () {
                    try { self._syncControls(); self._render(); } catch (e) {}
                    setTimeout(function () { try { self._paintOutputs(); self._paintHints(); self._paintPreview(); } catch (e) {} }, 60);
                });
                f.eventBus.on('period:undone', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('state:loaded', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('simulation:complete', function () { try { self._render(); } catch (e) {} });
            }
            var nb = this._el('nextPeriodBtn');
            if (nb) { nb.addEventListener('click', function () { setTimeout(function () { try { self._render(); } catch (e) {} }, 0); }); }
            var ub = this._el('undoBtn');
            if (ub) { ub.addEventListener('click', function () { setTimeout(function () { try { self._syncControls(); self._render(); } catch (e) {} }, 0); }); }
        }

        /* On resume or undo the sliders show the player own last values; the choices are left to the guard (each round starts blank). */
        _syncControls() {
            var st = this._state();
            if (!st) { return; }
            var d = st.decisions || {};
            var put = function (id, v) { var el = document.getElementById(id); if (el && el.tagName !== 'SELECT' && v !== undefined && v !== null && v !== '' && isFinite(Number(v))) { el.value = String(v); } };
            put('rightsizeInput', d.rightsize); put('grammageInput', d.grammage); put('streamsInput', d.streams);
            put('fibreInput', d.fibre); put('premiumInput', d.premium); put('logisticsInput', d.logistics);
            this._paintOutputs();
        }

        _render() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState;
            var over = this._runOver(st);
            var t = over ? CX_R : this._round();
            this._paintStatic(t, over);
            this._paintSteps(t, over);
            this._paintBriefing(t, over);
            this._paintKpis(ds);
            this._paintScore(ds);
            this._paintResult(ds);
            this._paintOutputs();
            this._paintHints();
            this._paintPreview();
            this._paintChartAlt(ds);
            var form = this._el('cxForm'), deb = this._el('debriefPanel');
            if (over) {
                if (form) { form.hidden = true; }
                if (deb) { deb.innerHTML = this._debriefHTML(ds, this.getPerformanceSummary(this._hist(st))); deb.hidden = false; }
            } else {
                if (form) { form.hidden = false; }
                if (deb) { deb.hidden = true; deb.innerHTML = ''; }
            }
            try { document.documentElement.lang = this._lang(); } catch (e) {}
        }

        _paintStatic(t, over) {
            var terms = ['butterfly', 'hierarchy', 'epr', 'pro', 'ecomod', 'symbiosis', 'lca', 'scope3', 'grammage', 'paas', 'cycles'];
            var html = '';
            for (var i = 0; i < terms.length; i++) { html += '<dt>' + this._t('g_' + terms[i]) + '</dt><dd>' + this._t('g_' + terms[i] + '_d') + '</dd>'; }
            this._set('cxGlossary', html);
            var tt = Math.min(t, CX_R);
            for (var r = 1; r <= CX_R; r++) { var fs = this._el('cxR' + r); if (fs) { var hid = (r !== tt) || over; if (fs.hidden !== hid) { fs.hidden = hid; } fs.disabled = hid; } }
            this._set('cxDecNote', this._t('dec_note_' + tt));
            var sc = function (a, b, c) { return '<span>' + a + '</span>' + (c ? '<span>' + c + '</span>' : '') + '<span>' + b + '</span>'; };
            this._set('rightsizeScale', sc(this._pct(0), this._pct(100), this._t('rs_mid')));
            this._set('grammageScale', sc('100 g/m²', '120 g/m²', this._t('gr_mid')));
            this._set('streamsScale', sc(this._t('st_lo'), this._t('st_hi')));
            this._set('fibreScale', sc(this._pct(68), this._pct(85), this._t('fb_mid')));
            this._set('premiumScale', sc(this._pct(0), this._pct(20)));
            this._set('logisticsScale', sc(this._m(0), this._m(1500)));
        }

        _paintSteps(t, over) {
            var html = '';
            var done = this._hist(this._state()).length;
            for (var i = 1; i <= CX_R; i++) {
                var cls = (i <= done) ? 'is-done' : (i === t && !over ? 'is-now' : '');
                html += '<li class="' + cls + '"><span>' + this._t('cal_short_' + i) + '</span></li>';
            }
            this._set('cxSteps', html);
            var c = this._el('cxCal');
            if (c) { var txt = over ? this._t('run_complete') : this._t('cal_' + t); if (c.textContent !== txt) { c.textContent = txt; } }
        }

        _paintBriefing(t, over) {
            var ds = (this._state() || {}).domainState || {};
            this._set('cxTag', over ? this._t('tag_done') : this._t('tag_' + t));
            this._set('cxBriefTitle', over ? this._t('brief_done_title') : this._t('brief_title_' + t));
            this._set('briefingText', over ? '<p>' + this._t('brief_done') + '</p>' : '<p>' + this._t('brief_' + t) + '</p>');
            var q = this._el('cxQuote');
            if (q) {
                var qt = over ? '' : this._t('quote_' + t);
                if (qt && qt !== 'quote_' + t) { this._set('cxQuote', qt); q.hidden = false; } else { q.hidden = true; }
            }
            var sig = [];
            if (!over) {
                if (t === 2 && ds.design === 'full' && ds.slip) { sig.push(this._t('sig_slip')); }
                if (t === 2 && ds.design === 'keep') { sig.push(this._t('sig_keep')); }
                if (t === 3 && ds.kraftSpike) { sig.push(this._t('sig_kraft')); }
                if (t === 3 && ds.biogasDown && ds.streams > 0) { sig.push(this._t(ds.streams >= 3 ? 'sig_biogas_net' : 'sig_biogas')); }
                if (t === 4 && ds.lca === 'audit') { sig.push(this._t(ds.R >= CPModel.M.R_T ? 'sig_audit_ok' : 'sig_audit_low')); }
                if (t === 4 && ds.lca === 'claim') { sig.push(this._t('sig_claim')); }
            }
            var sg = this._el('cxSignal');
            if (sg) { if (sig.length) { this._set('cxSignal', sig.join('<br>')); sg.hidden = false; } else { sg.hidden = true; } }
        }

        _delta(cur, prev, dec, good, unit) {
            if (prev == null) { return ''; }
            var d = cur - prev;
            if (Math.abs(d) < Math.pow(10, -(dec || 0)) / 2) { return '<span class="cx-flat">± 0</span> '; }
            var ok = good === 'down' ? d < 0 : d > 0;
            return '<span class="' + (ok ? 'cx-up' : 'cx-down') + '">' + (d > 0 ? '▲ ' : '▼ ') + this._num(Math.abs(d), dec) + (unit || '') + '</span> ';
        }

        _paintKpis(ds) {
            var h = ds.hist || [], last = h[h.length - 1];
            var M = CPModel.M;
            var s0 = last ? last.start : null;
            var pp = this._lang() === 'es' ? ' pp' : ' pp';
            this._set('rcyDisplay', this._pct(ds.R));
            this._set('rcySub', (last ? this._delta(ds.R, s0.R, 0, 'up', pp) : '') + this._t(ds.Rlater > ds.R ? 'rcy_sub_next' : 'rcy_sub', { n: this._pct(ds.Rlater), t: this._pct(M.R_T) }));
            this._set('recDisplay', this._pct(ds.rec));
            this._set('recSub', (last ? this._delta(ds.rec, s0.rec, 0, 'up', pp) : '') + this._t(ds.epr === 'certs' ? 'rec_sub_paper' : 'rec_sub', { t: this._pct(M.REC_T) }));
            this._set('credDisplay', this._num(ds.cred, 0) + '<small>/100</small>');
