        _paintScore(ds) {
            var h = ds.hist || [];
            var M = CPModel.M;
            if (!this._el('cxScoreCard')) { return; }
            var chip = function (ok, txt) { return '<span class="cx-gchip ' + (ok ? 'is-ok' : 'is-no') + '">' + (ok ? '✓ ' : '× ') + txt + '</span>'; };
            var gates = '<div class="cx-gates">' + chip(ds.rec >= M.REC_T && ds.epr !== 'certs', this._t('gate_rec', { v: this._pct(M.REC_T) }))
                + chip(ds.R >= M.R_T, this._t('gate_rcy', { v: this._pct(M.R_T) })) + chip(ds.access === 2, this._t('gate_panel')) + '</div>';
            if (!h.length) { this._set('cxScoreCard', '<p class="cx-h3">' + this._t('score_title') + '</p><p class="cx-muted">' + this._t('score_empty') + '</p>' + gates); return; }
            var p = ds.performance || {};
            var bar = function (label, v, cls) { var w = Math.round(100 * Math.max(0, Math.min(1, v))); return '<div class="cx-bar"><span class="cx-bar-l">' + label + '</span><span class="cx-bar-t"><span class="cx-bar-f ' + cls + '" style="width:' + w + '%"></span></span><span class="cx-bar-v">' + w + '</span></div>'; };
            var html = '<div class="cx-score-head"><span class="cx-h3">' + this._t('score_title') + '</span><span class="cx-score-n"><strong>' + p.overallScore + '</strong><small>/100</small></span>'
                + '<span class="cx-chip cx-chip-' + p.tier + '">' + this._t('perf_' + p.tier) + '</span></div>'
