        _paintResult(ds) {
            var h = ds.hist || [];
            if (!h.length) { this._set('cxResultPanel', '<p class="cx-h3">' + this._t('res_title0') + '</p><p class="cx-muted">' + this._t('res_empty') + '</p>'); return; }
            var r = h[h.length - 1], self = this;
            var li = [];
            var names = { sav: 'pp_sav', sym: 'pp_sym', prem: 'pp_prem', dmg: 'pp_dmg', design: 'pp_design', kraft: 'pp_kraft', fee: 'pp_fee', opex: 'pp_opex' };
            var arr = [];
            for (var key in r.parts) { if (r.parts.hasOwnProperty(key) && Math.abs(r.parts[key]) >= 1) { arr.push([key, r.parts[key]]); } }
            arr.sort(function (a, b) { return Math.abs(b[1]) - Math.abs(a[1]); });
            var pp = arr.slice(0, 5).map(function (x) { return self._t(names[x[0]]) + ' ' + self._sm(x[1]); }).join(' · ');
            li.push(this._t('res_ebitda', { e: this._m(r.ebitda), g: this._sm(r.gain), parts: pp || this._t('res_noparts') }));
            li.push(this._t('res_cash', { c: this._m(r.capex), a: this._m(r.start.cash), b: this._m(r.cash) }));
            var why = [];
            ['landed', 'landed_late', 'slip', 'keep', 'thin', 'rush', 'certs', 'biogas_absorbed', 'biogas_lost', 'kraft', 'claim', 'exposed', 'claim_held', 'audit_not_enough',
                'city_gap', 'deal', 'walked', 'accept', 'reject', 'vc_no_platform', 'nologistics', 'fined'].forEach(function (n) {
                if (r.notes.indexOf(n) >= 0) { why.push(self._t('why_' + n, { r: self._pct(r.R), c: self._num(r.cycles, 1), v: self._m(r.platform), f: self._m(CPModel.M.FINE) })); }
            });
            li.push(this._t('res_rcy', { a: this._pct(r.start.R), b: this._pct(r.R) }) + ' ' + this._t('res_rec', { a: this._pct(r.start.rec), b: this._pct(r.rec) }));
            li = li.concat(why);
            this._set('cxResultPanel', '<p class="cx-h3">' + this._t('res_title', { m: this._t('cal_' + r.t) }) + '</p><ul class="cx-res">' + li.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>');
        }

        _paintOutputs() {
            var t = this._round(), r = this._read(t);
            if (t === 1) { if (isFinite(r.rightsize)) { this._set('rightsizeOut', this._pct(r.rightsize)); } if (isFinite(r.grammage)) { this._set('grammageOut', r.grammage + ' g/m²'); } }
            if (t === 2 && isFinite(r.streams)) { this._set('streamsOut', r.streams + ' / 4'); }
            if (t === 3) { if (isFinite(r.fibre)) { this._set('fibreOut', this._pct(r.fibre)); } if (isFinite(r.premium)) { this._set('premiumOut', '+' + this._pct(r.premium)); } }
            if (t === 4 && isFinite(r.logistics)) { this._set('logisticsOut', this._m(r.logistics)); }
