        _paintHints() {
            var t = this._round(), r = this._read(t), st = this._state(), ds = (st && st.domainState) || {}, M = CPModel.M;
            if (t === 1) {
                this._set('designHint', r.design ? this._t('design_h_' + r.design) : this._t('pick_h'));
                var x = (r.rightsize || 0) / 100;
                this._set('rightsizeHint', this._t(x > 0.85 ? 'rightsize_h_rush' : 'rightsize_h', { c: this._m(350 * x + 900 * x * x), s: this._m(300 * x) }));
                var g = isFinite(r.grammage) ? r.grammage : 120;
                this._set('grammageHint', this._t('grammage_h', { s: this._m((120 - g) / 15 * 380) }));
            }
            if (t === 2) {
                var e = r.epr;
                this._set('eprHint', e ? this._t('epr_h_' + e, { f: this._m(CPModel.proFee(ds.Rlater || M.R0)), r: this._pct(ds.Rlater || M.R0) }) : this._t('pick_h'));
                var n = Math.round(r.streams || 0);
                this._set('streamsHint', this._t('streams_h', { s: this._m(M.STREAM_SETUP * n), c: this._m(M.STREAM_COORD * n * n), v: this._m(n ? M.STREAM_VAL * n * (1 + 0.2 * (n - 1)) : 0) }));
            }
            if (t === 3) {
                this._set('lcaHint', r.lca ? this._t('lca_h_' + r.lca) : this._t('pick_h'));
                this._set('fibreHint', this._t('fibre_h', { c: this._m(M.FIBRE_CAPEX * ((r.fibre || 68) - 68)) }));
                this._set('premiumHint', this._t('premium_h', { p: this._pct(r.premium || 0), r: this._pct(100 * CPModel.retention(r.premium || 0)) }));
            }
            if (t === 4) {
                this._set('modelHint', r.model ? this._t('model_h_' + r.model) : this._t('pick_h'));
                var cyc = CPModel.cyclesOf(r.logistics || 0, r.model || 'paas', ds.epr === 'own');
                this._set('logisticsHint', this._t('logistics_h', { c: this._num(cyc, 1), b: this._num(M.CYC_BREAK, 1) }));
                this._set('vcHint', r.vc ? this._t('vc_h_' + r.vc) : this._t('pick_h'));
            }
        }

        _paintPreview() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var t = this._round(), r = this._read(t);
            var pv = CPModel.preview(st.domainState, r, t);
            var cell = function (k, v, cls) { return '<div class="cx-pv' + (cls ? ' ' + cls : '') + '"><span>' + k + '</span><strong>' + v + '</strong></div>'; };
            var html = cell(this._t('pv_capex'), this._m(pv.capex)) + cell(this._t('pv_cash'), this._m(pv.cash), pv.cash < 0 ? 'is-neg' : '');
            if (t === 1) { html += cell(this._t('pv_run'), this._sm(pv.runRate), pv.runRate < 0 ? 'is-neg' : '') + cell(this._t('pv_rcy'), this._pct(pv.R)); }
            if (t === 2) { html += cell(this._t('pv_fee'), pv.fee == null || !r.epr ? '—' : this._m(pv.fee)) + cell(this._t('pv_sym'), this._sm(pv.sym)); }
            if (t === 3) { html += cell(this._t('pv_ret'), this._pct(100 * pv.ret)) + cell(this._t('pv_prem'), '+' + this._pct(pv.prem)); }
            if (t === 4) { html += cell(this._t('pv_cycles'), this._num(pv.cycles, 1), pv.cycles < CPModel.M.CYC_BREAK ? 'is-neg' : ''); }
            this._set('cxPreview', html + '<p class="cx-preview-note">' + this._t('pv_note_' + t) + '</p>');
        }

