            var self = this;
            this._set('circChartAlt', this._t('alt_circ') + ' ' + h.map(function (r) { return self._t('cal_short_' + r.t) + ': ' + self._pct(r.R) + ' / ' + self._pct(r.rec); }).join(' · '));
