        _relabelCharts() {
            var f = window.mySimulation;
            var charts = (f && ((f.uiManager && f.uiManager.charts) || f.charts || (f.chartManager && f.chartManager.charts))) || null;
            if (!charts) { return; }
            var cfg = this.getChartConfig();
            var data = this.getChartData(this._state());
            for (var id in cfg) {
                if (!cfg.hasOwnProperty(id)) { continue; }
                var ch = charts[id];
                if (!ch || !ch.data || !ch.options) { continue; }
                try {
                    ch.data.datasets.forEach(function (d, i) { if (cfg[id].data.datasets[i]) { d.label = cfg[id].data.datasets[i].label; } });
                    ch.options.plugins.title.text = cfg[id].options.plugins.title.text;
                    ch.options.scales.y.title.text = cfg[id].options.scales.y.title.text;
                    if (data[id]) { ch.data.labels = data[id].labels; }
                    ch.update('none');
                } catch (e) {}
            }
        }

