/* The decisions form never navigates: Enter in a field must not reload the sim. Done here rather than with an
   inline onsubmit so that the view carries no script (the sandboxed Open preview blocks inline handlers). */
document.addEventListener("submit", function (e) {
    if (e.target && e.target.id === "cxForm") { e.preventDefault(); }
}, true);
